// SPDX-License-Identifier: AGPL-3.0-only
//! Review of check 2 of #2449: typed reads against raw reads. Each test is one case whose host answers and whose
//! TS output come from running the TS verb under node (`runVerb` at 65f6b89c7); each fails today at the first
//! assertion `holds` makes. Every run is bounded to ten seconds, so a hang fails in seconds.
#![allow(clippy::result_large_err, clippy::type_complexity, clippy::too_many_arguments, clippy::large_enum_variant, dead_code)]

#[path = "cli_b/common.rs"]
mod common;

use common::Case;
use std::sync::mpsc;
use std::time::Duration;

fn case(json: &str) -> Case {
    serde_json::from_str(json).expect("the case parses")
}

fn bounded(c: Case) {
    let (tx, rx) = mpsc::channel();
    std::thread::spawn(move || {
        let run = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| common::holds(&c)));
        let _ = tx.send(run.map_err(|e| {
            e.downcast_ref::<String>()
                .cloned()
                .or_else(|| e.downcast_ref::<&str>().map(|s| (*s).to_owned()))
                .unwrap_or_else(|| "panic".to_owned())
        }));
    });
    match rx.recv_timeout(Duration::from_secs(10)) {
        Ok(Ok(())) => {}
        Ok(Err(message)) => panic!("{message}"),
        Err(_) => panic!("the line did not finish in ten seconds"),
    }
}

